   923  /* Validate PNG keyword *str, *str must be 80 bytes */
   924  static int check_png_keyword(const char str[80])
   925  {
   926      if(str == NULL) return 1;
   927      char *end = memchr(str, '\0', 80);
   928
   929      if(end == NULL) return 1; /* unterminated string */
   930      if(end == str) return 1; /* zero-length string */
   931      if(str[0] == ' ') return 1; /* leading space */
   932      if(end[-1] == ' ') return 1; /* trailing space */
   933      if(strstr(str, "  ") != NULL) return 1; /* consecutive spaces */
   934
   935      uint8_t c;
   936      while(str != end)
   937      {
   938          memcpy(&c, str, 1);
   939
   940          if( (c >= 32 && c <= 126) || (c >= 161) ) str++;
   941          else return 1; /* invalid character */
   942      }
   943
   944      return 0;
   945  }
   946
   947  /* Validate PNG text *str up to 'len' bytes */
   948  static int check_png_text(const char *str, size_t len)
   949  {/* XXX: are consecutive newlines permitted? */
   950      if(str == NULL || len == 0) return 1;
   951
   952      uint8_t c;
   953      size_t i = 0;
   954      while(i < len)
   955      {
   956          memcpy(&c, str + i, 1);
   957
   958          if( (c >= 32 && c <= 126) || (c >= 161) || c == 10) i++;
   959          else return 1; /* invalid character */
   960      }
   961
   962      return 0;
   963  }
