    27  {
    28      if(size < 2) return 0;
    29
    30      int flags = data[0];
    31      int fmt = data[1] & 0x7F;
    32      int stream = data[1] >> 7;
    33
    34      data+=2; size-=2;
    35
    36      int ret;
    37      unsigned char *out = NULL;
    38
    39      spng_ctx *ctx = spng_ctx_new(0);
    40      if(ctx == NULL) return 0;
    41
    42      struct buf_state state;
    43      state.data = data;
    44      state.bytes_left = size;
    45
    46      if(stream) ret = spng_set_png_stream(ctx, buffer_read_fn, &state);
    47      else ret = spng_set_png_buffer(ctx, (void*)data, size);
    48
    49      if(ret) goto err;
    50
    51      spng_set_image_limits(ctx, 200000, 200000);
    52
    53      spng_set_chunk_limits(ctx, 4 * 1000 * 1000, 8 * 1000 * 1000);
    54
    55      spng_set_crc_action(ctx, SPNG_CRC_USE, SPNG_CRC_USE);
    56
    57      size_t out_size;
    58      if(spng_decoded_image_size(ctx, fmt, &out_size)) goto err;
    59
    60      if(out_size > 80000000) goto err;
    61
    62      out = (unsigned char*)malloc(out_size);
    63      if(out == NULL) goto err;
    64
    65      if(spng_decode_image(ctx, out, out_size, fmt, flags)) goto err;
    66
    67  err:
    68      spng_ctx_free(ctx);
    69      if(out != NULL) free(out);
    70
    71      return 0;
    72  }

