   285  static inline int read_data(spng_ctx *ctx, size_t bytes)
   286  {
   287      if(ctx == NULL) return 1;
   288      if(!bytes) return 0;
   289
   290      if(ctx->streaming && (bytes > ctx->data_size))
   291      {
   292          void *buf = spng__realloc(ctx, ctx->data, bytes);
   293          if(buf == NULL) return SPNG_EMEM;
