   295          ctx->data = buf;
   296          ctx->data_size = bytes;
   297      }
   298
   299      int ret;
   300      ret = ctx->read_fn(ctx, ctx->read_user_ptr, ctx->data, bytes);
   301      if(ret) return ret;
   302
   303      ctx->bytes_read += bytes;
   304      if(ctx->bytes_read < bytes) return SPNG_EOVERFLOW;
   305
   306      return 0;
   307  }
