   337  /* Read and validate the current chunk's crc and the next chunk header */
   338  static inline int read_header(spng_ctx *ctx, int *discard)
   339  {
   340      if(ctx == NULL) return 1;
   341
   342      int ret;
   343      struct spng_chunk chunk = { 0 };
   344
   345      ret = read_and_check_crc(ctx);
   346      if(ret)
   347      {
   348          if(ret == SPNG_CRC_DISCARD)
   349          {
   350              if(discard != NULL) *discard = 1;
   351          }
   352          else return ret;
   353      }
   354
   355      ret = read_data(ctx, 8);
   356      if(ret) return ret;
   357
   358      chunk.offset = ctx->bytes_read - 8;
   359
   360      chunk.length = read_u32(ctx->data);
   361
   362      memcpy(&chunk.type, ctx->data + 4, 4);
   363
   364      if(chunk.length > png_u32max) return SPNG_ECHUNK_SIZE;
   365
   366      ctx->cur_chunk_bytes_left = chunk.length;
   367
   368      ctx->cur_actual_crc = crc32(0, NULL, 0);
   369      ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, chunk.type, 4);
   370
   371      memcpy(&ctx->current_chunk, &chunk, sizeof(struct spng_chunk));
   372
