  2344  static int buffer_read_fn(spng_ctx *ctx, void *user, void *data, size_t n)
  2345  {
  2346      if(n > ctx->bytes_left) return SPNG_IO_EOF;
  2347
  2348      ctx->data = ctx->data + ctx->last_read_size;
  2349
  2350      ctx->last_read_size = n;
  2351      ctx->bytes_left -= n;
  2352
  2353      return 0;
  2354  }
