  2356  int spng_set_png_buffer(spng_ctx *ctx, void *buf, size_t size)
  2357  {
  2358      if(ctx == NULL || buf == NULL) return 1;
  2359      if(!ctx->valid_state) return SPNG_EBADSTATE;
  2360      if(ctx->encode_only) return SPNG_ENCODE_ONLY;
  2361
  2362      if(ctx->data != NULL) return SPNG_EBUF_SET;
  2363
  2364      ctx->data = buf;
  2365      ctx->png_buf = buf;
  2366      ctx->data_size = size;
  2367      ctx->bytes_left = size;
  2368
  2369      ctx->read_fn = buffer_read_fn;
  2370
  2371      return 0;
  2372  }
